import pandas as pd
from sklearn.decomposition import PCA
import matplotlib.pyplot as plt

def task_func(df):
    if df is None or df.empty:
        return 0, 0

    list_col = None
    for col in df.columns:
        non_null = df[col].dropna()
        if not non_null.empty and non_null.apply(lambda x: isinstance(x, (list, tuple))).all():
            list_col = col
            break

    if list_col is None:
        return 0, 0

    data = pd.DataFrame(df[list_col].tolist(), index=df.index)
    data = data.apply(pd.to_numeric, errors="coerce").dropna(axis=0, how="any")

    if data.empty or data.shape[0] < 2 or data.shape[1] == 0:
        return 0, 0

    pca = PCA()
    pca.fit(data)
    explained_variance_ratio = pca.explained_variance_ratio_

    _, ax = plt.subplots()
    ax.bar(range(1, len(explained_variance_ratio) + 1), explained_variance_ratio)
    ax.set_title("Explained Variance Ratio of Principal Components")
    ax.set_xlabel("Principal Component")
    ax.set_ylabel("Explained Variance Ratio")

    return explained_variance_ratio, ax
